// winmm.dll pass-through (alpha). MHW delay-imports winmm.dll (the packed exe's
// only static import is KERNEL32), so the alpha DLL is shipped under that name
// in the game folder: Windows maps it at the game's first winmm call, or at
// process start when an early module imports winmm statically (Steam's
// GameOverlayRenderer64.dll does). Either way it precedes the device: in game-52
// the D3D12CreateDevice hook caught the game's own call. Every winmm export
// (winmm_exports.def, generated by tools/gen_winmm_proxy.py) jumps through
// winmm_table, filled here from the system winmm.dll during DLL_PROCESS_ATTACH
// (CRT static initialization, before any importer can call through it).
// Loaded under any other name (MO2 force-load) the exports are simply unused.
#include <windows.h>
#include <array>
#include <cstdint>
#include <cwchar>

namespace {
struct Export { const char *name; unsigned ordinal; };
constexpr Export exports[]{
#include "winmm_exports.inc"
};
// A function the running Windows lacks: callers get 0 (x64 callers clean up).
extern "C" std::uintptr_t winmm_missing() { return 0; }
}
extern "C" void *winmm_table[std::size(exports)];

namespace {
struct Pass {
    Pass() noexcept {
        for (auto &entry : winmm_table) entry = reinterpret_cast<void *>(&winmm_missing);
        std::array<wchar_t, MAX_PATH> path{};
        const auto n = GetSystemDirectoryW(path.data(), static_cast<UINT>(path.size()));
        if (!n || n + 11 >= path.size()) return;
        wcscpy_s(path.data() + n, path.size() - n, L"\\winmm.dll");
        const HMODULE system = LoadLibraryW(path.data());
        if (!system) return;
        for (unsigned i = 0; i < std::size(exports); ++i) {
            const auto *name = exports[i].name ? exports[i].name : MAKEINTRESOURCEA(exports[i].ordinal);
            if (const auto target = GetProcAddress(system, name)) winmm_table[i] = reinterpret_cast<void *>(target);
        }
    }
} pass;
}
